                return live_out
            if hasattr(stmt.value, "s") and isinstance(stmt.value.s, str):
                # python 3.7
                return live_out
        if isinstance(stmt, ast.FunctionDef):
            return live_out
        try:
            if stmt.value.func.id == "print":
