                return live_out
        except (TypeError, AttributeError):
            pass
        raise ValueError(
            debuginfo.DebugInfo(stmt, converter).msg(
                f"Unsupported statement type {type(stmt)!r}."
            )
        )

    assert isinstance(fun, ast.FunctionDef)
    live: set[Any] = set()
    for s in reversed(fun.body):
        live = visit(s, live)


